        if (totalTokens > TOKEN_BUDGET) {
            console.log('\n[Token 预算耗尽]');
            break;
        }

        if (!hasToolCall) {
            if (fullText) console.log();
            break;
        }

        console.log('  → 继续下一步...');
    }

    if (step >= MAX_STEPS) {
        console.log('\n[达到最大步数]');
    }
}
